files.content:
*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  height: 100%;
}

body {
  display: grid;
  place-items: center;
  min-width: 360px;
  height: inherit;
  margin: 0;
  font-family: 'Open Sans', sans-serif;
  font-size: 18px;
  background-image: url(https://code.s3.yandex.net/web-code/images/dotted.svg);
}

h1,
p,
ul,
li {
  margin: 0;
  padding: 0;
}

form::before {
  content: 'Отправка каждого сообщения немного нагревает Арктический лёд';
  position: absolute;
  top: 0;
  left: -1px;
  width: calc(100% + 2px);
  border: 1px solid #000;
  border-bottom: none;
  padding: 10px;
  opacity: 0;
  color: #fff;
  font-weight: bold;
  font-size: 12px;
  background-color: #5f0dee;
  transition: opacity 0.3s ease-in-out;
  translate: 0 -100%;
}

form:focus-within::before {
  opacity: 1;
}

form::after {
  content: 'Сообщение не отправлено';
  position: absolute;
  bottom: 0;
  left: -1px;
  width: calc(100% + 2px);
  border: 1px solid #000;
  border-top: none;
  padding: 10px;
  opacity: 0;
  color: #000;
  font-weight: bold;
  font-size: 12px;
  background-color: #feafe8;
  transition: opacity 0.3s ease-in-out;
  translate: 0 100%;
}
form.form_is-after-visible::after {
  opacity: 1;
}
